  1	<?php
  2	
  3	namespace Modules\AI\Domain\Decision;
  4	
  5	use OGame\Factories\GameMissionFactory;
  6	use OGame\GameObjects\Models\Abstracts\GameObject;
  7	use OGame\GameObjects\Models\Calculations\CalculationType;
  8	use OGame\GameObjects\Models\Enums\GameObjectType;
  9	use OGame\GameObjects\Models\UnitObject;
 10	use OGame\Models\Enums\PlanetType;
 11	use OGame\Services\ObjectService;
 12	use OGame\Services\PlanetService;
 13	use OGame\Services\PlayerService;
 14	
 15	/**
 16	 * The building this planet still needs before the next thing the account wants to produce is
 17	 * possible at all.
 18	 *
 19	 * A seeded account owns nothing, so without this the account grows resources forever and never owns
 20	 * a laboratory or a shipyard -- which is how six of its capabilities became permanently unreachable.
 21	 * The chain is what connects the account's ambitions to the buildings that gate them.
 22	 *
 23	 * Nothing here names an object. The ambitions are whatever the host offers as research or as a unit,
 24	 * and the requirements are the host's own recursive requirement graph, so a module or an expansion
 25	 * that adds a ship, a technology or a building is part of the plan the moment the host knows about
 26	 * it -- and a host that changes a prerequisite changes this plan with no edit here.
 27	 *
 28	 * The module's only policy is the order, and it is the level the host asks for: the easiest unlock
 29	 * first. A player picks up the small prerequisites as they go, and ordering by the requirement
 30	 * rather than by the building is what keeps the plan from rushing the largest shipyard in the game
 31	 * while the account still has no laboratory. Only the level the host asks for counts, because level
 32	 * one of a robotics factory never unlocks a shipyard and treating "something is built" as done would
 33	 * stall the chain one step below its goal.
 34	 *
 35	 * The account works on one ambition at a time: the cheapest thing it cannot yet produce. Satisfying
 36	 * the union of every ambition's prerequisites instead is a ladder with no top -- the catalogue always
 37	 * names one more deep unlock, so the chain never finishes, the economy never gets a turn, and the
 38	 * account ends the day with a level-seven shipyard standing over level-three mines. A player picks a
 39	 * goal, stands what it needs, and goes back to mining; the next goal gets its turn on a later
 40	 * session, and the economy ranks in between.
 41	 *
 42	 * A step the planet cannot pay for because it produces none of a resource the step costs is blocked
 43	 * the same way a missing level is, so the producer of that resource is a chain step too: a player
 44	 * mines what they are short of, and the synthesizer stands before the robotics factory exactly the
 45	 * way the laboratory does.
 46	 *
 47	 * A step is whatever queue accepts it: the host's catalogue holds buildings and technologies beside
 48	 * each other, and a technology gating a laboratory is as much a prerequisite as the laboratory
 49	 * itself. Which queue takes the step is the planner's question, answered from the host's object type.
 50	 */
 51	class FacilityChain
 52	{
 53	    /** The resources a planet mines; energy is absent because capacity has its own rule ahead of the chain. */
 54	    private const MINED_RESOURCES = ['metal', 'crystal', 'deuterium'];
 55	
 56	    /** The moon station the account wants; module taste, never a source of truth for its requirements. */
 57	    private const PHALANX_STATION = 'sensor_phalanx';
 58	
 59	    /** The second moon station, only useful as a pair; module taste, requirements host-read. */
 60	    private const JUMP_GATE_STATION = 'jump_gate';
 61	
 62	    /** @return list<BuildCandidate> the unmet prerequisites of the one ambition in hand, easiest unlock first */
 63	    public function pending(PlanetService $planet): array
 64	    {
 65	        $ordered = [];
 66	        $producers = [];
 67	
 68	        $ambition = $this->nextAmbition($planet);
 69	        if ($ambition !== null) {
 70	            foreach (ObjectService::getRecursiveRequirements($ambition->machine_name) as $machineName => $level) {
 71	                $this->addRequirement($planet, $machineName, $level, $ordered, $producers);
 72	            }
 73	        }
 74	
 75	        // Capability research (R2): a research a host mission waits on is a step in its own right,
 76	        // whether or not any unit needs it. The chain is the module's only research source, so
 77	        // without this a leaf technology that unlocks a mission -- astrophysics for colonise and
 78	        // expedition -- is never reached, and that mission's whole capability stays unreachable
 79	        // however long the account plays. The technology is never named here: it comes from the
 80	        // mission's own answer, so a mission a mod adds is climbed once the host knows it.
 81	        foreach ($this->missionRequiredResearch() as $machineName => $level) {
 82	            $this->addRequirement($planet, $machineName, $level, $ordered, $producers, 'capability');
 83	
 84	            foreach (ObjectService::getRecursiveRequirements($machineName) as $prerequisite => $prerequisiteLevel) {
 85	                $this->addRequirement($planet, $prerequisite, $prerequisiteLevel, $ordered, $producers);
 86	            }
 87	        }
 88	
 89	        // SP8: a slot-bound account — zero free fleet slots — reaches the technology that
 90	        // raises the ceiling, never named here (R11 publishes the object behind the value).
 91	        foreach ($this->fleetSlotCeilingResearch($planet) as $machineName => $level) {
 92	            $this->addRequirement($planet, $machineName, $level, $ordered, $producers, 'slot-ceiling');
 93	        }
 94	
 95	        // A planet-capped account — every colony slot it has unlocked is already settled —
 96	        // reaches the technology that raises the planet ceiling, never named here either. The
 97	        // mission's own answer only asks for the level that first makes colonising possible, so
 98	        // without this the account settles its one colony and stops with capacity to spare.
 99	        foreach ($this->planetCeilingResearch($planet) as $machineName => $level) {
100	            $this->addRequirement($planet, $machineName, $level, $ordered, $producers, 'planet-ceiling');
101	        }
102	
103	        // A moon the account owns wants its sensor phalanx: the station is module taste, and
104	        // the host's own recursive requirement graph puts the lunar base first (RV-008).
105	        if ($planet->getPlanetType() === PlanetType::Moon) {
106	            $this->addRequirement($planet, self::PHALANX_STATION, 1, $ordered, $producers, 'moon-station');
107	
108	            foreach (ObjectService::getRecursiveRequirements(self::PHALANX_STATION) as $machineName => $level) {
109	                $this->addRequirement($planet, $machineName, $level, $ordered, $producers, 'moon-station');
110	            }
111	
112	            // A jump gate is only a save as a pair, so it is a chain step once the account owns
113	            // two moons (RV-009).
114	            if ($this->hasTwoMoons($planet)) {
115	                $this->addRequirement($planet, self::JUMP_GATE_STATION, 1, $ordered, $producers, 'moon-station');
116	
117	                foreach (ObjectService::getRecursiveRequirements(self::JUMP_GATE_STATION) as $machineName => $level) {
118	                    $this->addRequirement($planet, $machineName, $level, $ordered, $producers, 'moon-station');
119	                }
120	            }
121	        }
122	
123	        // A planet that holds no defence at all while a sibling already stands a wall wants the
124	        // facilities the host's own smallest defence unit needs: the yard cannot take a defence order
125	        // before those stand, so the planet stays naked beside its walled sibling forever, and the
126	        // wall keeps growing where it already is (measured live 2 Oct 2026: planets at zero defence
127	        // beside a sibling holding 21,084 units). The unit is never named: it is the cheapest the
128	        // host's defence registry offers, and its prerequisites are the host's recursive graph.
129	        foreach ($this->wallPrerequisites($planet) as $machineName => $level) {
130	            $this->addRequirement($planet, $machineName, $level, $ordered, $producers, 'wall-prerequisite');
131	        }
132	
133	        // A prerequisite requested at several levels appears once per level, so the account climbs
134	        // to the next one it is missing.
135	        $this->sortOrdered($ordered, $planet);
136	
137	        return $this->withProducers($ordered, $producers, $planet);
138	    }
139	
140	    /**
141	     * The facilities the host's own smallest defence unit needs, for the planet the rule applies to,
142	     * as a list of its own.
143	     *
144	     * `pending()` already carries them among the chain's steps, but a chain step is one candidate the
145	     * economy ranks against the mines: a planet whose stock overflows is spending, and the surplus pass
146	     * asked first, so the wall's prerequisites never got their turn and the planet stayed naked beside
147	     * its walled sibling (measured live 2 Oct 2026: 7-8 planets at zero defence while one held the
148	     * wall). The building planner gives this list its own pass ahead of the economy, and nothing is
149	     * named here: the unit is the cheapest the host registers and the steps are the host's own graph.
150	     *
151	     * @return list<BuildCandidate>
152	     */
153	    public function wallPending(PlanetService $planet): array
154	    {
155	        // Own pass, ahead of the economy: the facilities the wall waits on are a fix, not a choice.
156	        $ordered = [];
157	        $producers = [];
158	
159	        foreach ($this->wallPrerequisites($planet) as $machineName => $level) {
160	            $this->addRequirement($planet, $machineName, $level, $ordered, $producers, 'wall-prerequisite');
161	        }
162	
163	        $this->sortOrdered($ordered, $planet);
164	
165	        return $this->withProducers($ordered, $producers, $planet);
166	    }
167	
168	    /**
169	     * The smallest defence unit a planet that stands bare beside a walled sibling owes from its own
170	     * yard, or null when it owes none yet.
171	     *
172	     * The prerequisite pass above stands what the unit waits on, and the unit planner can only order
173	     * a batch the host takes whole -- so a planet whose yard is already ready has to let its balance
174	     * reach the unit's price before any order exists. Left to the routine economy that balance never
175	     * gets there: a mine is always cheaper than a unit, so every login spends the trickle and the
176	     * planet stays naked beside its sibling's wall (QUAL-003: 3 planets at zero defence while one
177	     * held 1,312 units). The unit named here is the one the account holds the planet back for, and
178	     * no unit is named by this module: it is the smallest the host's registry prices.
179	     */
180	    public function wallUnitStep(PlanetService $planet): ?string
181	    {
182	        if (! $this->nakedBesideWalled($planet) || $this->wallPending($planet) !== []) {
183	            return null;
184	        }
185	
186	        $unit = $this->smallestDefenceUnit();
187	        if ($unit === null || ! ObjectService::objectRequirementsMet($unit->machine_name, $planet)) {
188	            return null;
189	        }
190	
191	        return $unit->machine_name;
192	    }
193	
194	    /**
195	     * What this planet keeps in hand for the wall unit it owes, or null when it owes none yet.
196	     *
197	     * The economy spends every login's trickle on the next mine, so a planet too poor to pay for the
198	     * unit at login never reaches its price and stays bare beside its sibling's wall however long the
199	     * account plays (QUAL-003: 3 planets at zero defence while one held 1,312 units). The price is the
200	     * host's own, so no unit or number is named here.
201	     */
202	    public function wallUnitHold(PlanetService $planet): ?Resources
203	    {
204	        $machineName = $this->wallUnitStep($planet);
205	
206	        return $machineName === null ? null : ObjectService::getObjectPrice($machineName, $planet);
207	    }
208	
209	    /**
210	     * The chain's stated order: unmet host prerequisites first, then facilities before research
211	     * (an ordinary player stands the factory before chasing the technology or yard it enables), then
212	     * by the level asked for and the price of the step.
213	     *
214	     * @param array<string, array{level: int, candidate: BuildCandidate}> $ordered
215	     */
216	    private function sortOrdered(array &$ordered, PlanetService $planet): void
217	    {
218	        usort($ordered, function (array $left, array $right) use ($planet): int {
219	            $leftObject = ObjectService::getObjectById($left['candidate']->buildingId);
220	            $rightObject = ObjectService::getObjectById($right['candidate']->buildingId);
221	            $dependencies = $this->unmetDependencyCount($leftObject->machine_name, $planet)
222	                <=> $this->unmetDependencyCount($rightObject->machine_name, $planet);
223	            if ($dependencies !== 0) {
224	                return $dependencies;
225	            }
226	
227	            $type = ((int) ($leftObject->type === GameObjectType::Research))
228	                <=> ((int) ($rightObject->type === GameObjectType::Research));
229	            if ($type !== 0) {
230	                return $type;
231	            }
232	
233	            return [$left['level'], ObjectService::getObjectPrice($leftObject->machine_name, $planet)->sum()]
234	                <=> [$right['level'], ObjectService::getObjectPrice($rightObject->machine_name, $planet)->sum()];
235	        });
236	    }
237	
238	    /**
239	     * The final step list: the producers first, because a step the planet cannot pay for is
240	     * unreachable until its producer stands, then the ordered prerequisites.
241	     *
242	     * @param array<string, array{level: int, candidate: BuildCandidate}> $ordered
243	     * @param array<string, GameObject> $producers
244	     * @return list<BuildCandidate>
245	     */
246	    private function withProducers(array $ordered, array $producers, PlanetService $planet): array
247	    {
248	        return [...$this->producerSteps($producers, $planet), ...array_map(static fn (array $entry): BuildCandidate => $entry['candidate'], $ordered)];
249	    }
250	
251	    /**
252	     * The research every host mission waits on, merged: machine name => the highest level any mission
253	     * asks for.
254	     *
255	     * The module names no technology. It asks the host's own mission catalogue what each mission
256	     * requires, so a mission a mod or an expansion adds makes its technology a chain step the moment
257	     * the host knows about it (gate 1). This is what makes a capability the account cannot yet run
258	     * -- colonise, expedition -- reachable at all: the research gate is a step like any other.
259	     *
260	     * @return array<string, int>
261	     */
262	    /** @return array<string, int> */
263	    private function missionRequiredResearch(): array
264	    {
265	        $required = [];
266	
267	        foreach (GameMissionFactory::getMissionClasses() as $mission) {
268	            foreach ($mission::getRequiredResearch() as $machineName => $level) {
269	                $required[$machineName] = max($required[$machineName] ?? 0, $level);
270	            }
271	        }
272	
273	        return $required;
274	    }
275	
276	    /**
277	     * The technology that raises the fleet-slot ceiling, as a chain step only when the account is
278	     * slot-bound (zero free slots). The object is never named: it is the one the host publishes as
279	     * carrying `MAX_FLEET_SLOTS` (host obligation R11).
280	     *
281	     * @return array<string, int>
282	     */
283	    private function fleetSlotCeilingResearch(PlanetService $planet): array
284	    {
285	        $player = $planet->getPlayer();
286	
287	        if ($player === null || $player->getFleetSlotsMax() - $player->getFleetSlotsInUse() > 0) {
288	            return [];
289	        }
290	
291	        $ceiling = ObjectService::getObjectByCalculationType(CalculationType::MAX_FLEET_SLOTS);
292	
293	        return $ceiling === null ? [] : [$ceiling->machine_name => 1];
294	    }
295	
296	    /**
297	     * The technology that raises the planet ceiling, as a chain step only while the account holds as
298	     * many planets as the host allows it. The object is never named: it is the one the host publishes
299	     * as carrying `MAX_COLONIES`, so a mod-added technology behind that value takes the step with no
300	     * edit here. One level is asked for at a time -- the account climbs the technology the way it
301	     * stands any other prerequisite, and the step disappears the moment the host reports a free slot.
302	     *
303	     * @return array<string, int>
304	     */
305	    private function planetCeilingResearch(PlanetService $planet): array
306	    {
307	        $player = $planet->getPlayer();
308	
309	        if ($player === null || $player->planets->planetCount() < $player->getMaxPlanetAmount()) {
310	            return [];
311	        }
312	
313	        $ceiling = ObjectService::getObjectByCalculationType(CalculationType::MAX_COLONIES);
314	
315	        return $ceiling === null ? [] : [$ceiling->machine_name => $player->getResearchLevel($ceiling->machine_name) + 1];
316	    }
317	
318	    /**
319	     * Add one unmet requirement as a chain step, and remember the producer of a resource the step
320	     * cannot pay for.
321	     *
322	     * The same prerequisite can be named twice -- by the ambition in hand and by a mission's
323	     * technology -- so the list is keyed by machine name and keeps the highest level asked for, and a
324	     * step is never offered twice.
325	     *
326	     * @param array<string, array{level: int, candidate: BuildCandidate}> $ordered
327	     * @param array<string, GameObject> $producers
328	     */
329	    private function addRequirement(PlanetService $planet, string $machineName, int $level, array &$ordered, array &$producers, string $reason = 'chain'): void
330	    {
331	        if ($this->currentLevel($planet, $machineName) >= $level) {
332	            return;
333	        }
334	
335	        if (($ordered[$machineName]['level'] ?? 0) >= $level) {
336	            return;
337	        }
338	
339	        $ordered[$machineName] = ['level' => $level, 'candidate' => app()->makeWith(BuildCandidate::class, [
340	            'buildingId' => ObjectService::getObjectByMachineName($machineName)->id,
341	            'reason' => $reason . ':' . $machineName,
342	        ])];
343	
344	        foreach ($this->producersOfShortResources($machineName, $planet) as $object) {
345	            $producers[$object->machine_name] = $object;
346	        }
347	    }
348	
349	    /**
350	     * The cheapest thing this account cannot yet produce, or null once it can produce everything.
351	     *
352	     * The host's own catalogue ordered cheapest-first is the goal list, so the goal is the easiest
353	     * unlock still available and no object is named here. An ambition whose prerequisites all stand
354	     * is not a goal -- there is nothing left to build towards -- so it is skipped rather than
355	     * rebuilt, which is what lets the chain finish instead of asking for the same shipyard forever.
356	     */
357	    private function nextAmbition(PlanetService $planet): ?GameObject
358	    {
359	        foreach ($this->ambitions($planet) as $ambition) {
360	            foreach (ObjectService::getRecursiveRequirements($ambition->machine_name) as $machineName => $level) {
361	                if ($this->currentLevel($planet, $machineName) < $level) {
362	                    return $ambition;
363	                }
364	            }
365	        }
366	
367	        return null;
368	    }
369	
370	    private function unmetDependencyCount(string $machineName, PlanetService $planet): int
371	    {
372	        $missing = 0;
373	
374	        foreach (ObjectService::getRecursiveRequirements($machineName) as $requiredName => $requiredLevel) {
375	            if ($this->currentLevel($planet, $requiredName) < $requiredLevel) {
376	                $missing++;
377	            }
378	        }
379	
380	        return $missing;
381	    }
382	
383	    /**
384	     * The producers of the resources a step costs that this planet has no income of.
385	     *
386	     * A step short on a resource the planet cannot make can never be paid for, however the economy
387	     * ranking amortises it, so the producer of that resource is as much a prerequisite as a missing
388	     * level is. A resource with income is not short: the account is merely saving up, and waiting
389	     * for income is what a player does then.
390	     *
391	     * @return list<GameObject>
392	     */
393	    private function producersOfShortResources(string $machineName, PlanetService $planet): array
394	    {
395	        $price = ObjectService::getObjectPrice($machineName, $planet);
396	        $producers = [];
397	
398	        foreach (self::MINED_RESOURCES as $resource) {
399	            if ($price->{$resource}->get() <= $planet->{$resource}()->get() || $this->incomeOf($planet, $resource) > 0.0) {
400	                continue;
401	            }
402	
403	            foreach ($this->producersOf($resource, $planet) as $object) {
404	                $producers[$object->machine_name] = $object;
405	            }
406	        }
407	
408	        return array_values($producers);
409	    }
410	
411	    private function incomeOf(PlanetService $planet, string $resource): float
412	    {
413	        return match ($resource) {
414	            'metal' => $planet->getMetalProductionPerHour(),
415	            'crystal' => $planet->getCrystalProductionPerHour(),
416	            'deuterium' => $planet->getDeuteriumProductionPerHour(),
417	            default => 0.0,
418	        };
419	    }
420	
421	    /** @return list<GameObject> the objects the host itself reports as producing this resource */
422	    private function producersOf(string $resource, PlanetService $planet): array
423	    {
424	        $producers = [];
425	
426	        foreach (ObjectService::getGameObjectsWithProduction() as $object) {
427	            if (!BuildingQueueObject::accepts($object->machine_name)) {
428	                continue;
429	            }
430	
431	            if ($planet->getObjectProduction($object->machine_name, 1, true)->{$resource}->get() <= 0.0) {
432	                continue;
433	            }
434	
435	            $producers[] = $object;
436	        }
437	
438	        return $producers;
439	    }
440	
441	    /**
442	     * @param array<string, GameObject> $producers
443	     * @return list<BuildCandidate> cheapest first, the same convention as the capacity rule
444	     */
445	    private function producerSteps(array $producers, PlanetService $planet): array
446	    {
447	        $objects = array_values($producers);
448	
449	        usort($objects, static fn (GameObject $left, GameObject $right): int =>
450	            ObjectService::getObjectPrice($left->machine_name, $planet)->sum()
451	            <=> ObjectService::getObjectPrice($right->machine_name, $planet)->sum());
452	
453	        return array_map(static fn (GameObject $object): BuildCandidate => app()->makeWith(BuildCandidate::class, [
454	            'buildingId' => $object->id,
455	            'reason' => 'chain:' . $object->machine_name,
456	        ]), $objects);
457	    }
458	
459	    /**
460	     * How far this account already is with one prerequisite.
461	     *
462	     * The host keeps a planet's levels on the planet and a technology's on the player, so asking the
463	     * planet for a technology answers zero every time and would offer the same step forever.
464	     */
465	    private function currentLevel(PlanetService $planet, string $machineName): int
466	    {
467	        $isResearch = ObjectService::getObjectByMachineName($machineName)->type === GameObjectType::Research;
468	
469	        if (!$isResearch) {
470	            return $planet->getObjectLevel($machineName);
471	        }
472	
473	        // A planet always has an owner on the host; the nullable signature is the
474	        // host's, so a missing player reads as level zero rather than crashing a
475	        // decision on data the host itself would not normally be without.
476	        return $planet->getPlayer()?->getResearchLevel($machineName) ?? 0;
477	    }
478	
479	    /**
480	     * The facilities the host's own smallest defence unit requires, or none when this planet does not
481	     * need them.
482	     *
483	     * A planet needs them exactly when it holds no defence while a sibling of the same account
484	     * already stands one: that is the account past its opening, with a wall it built everywhere it
485	     * could reach, so the reasons the unit planner has for waiting no longer apply and the facility
486	     * that gates the wall is as much a prerequisite as a laboratory gating a technology.
487	     *
488	     * @return array<string, int>
489	     */
490	    private function wallPrerequisites(PlanetService $planet): array
491	    {
492	        if (! $this->nakedBesideWalled($planet)) {
493	            return [];
494	        }
495	
496	        $unit = $this->smallestDefenceUnit();
497	
498	        return $unit === null ? [] : ObjectService::getRecursiveRequirements($unit->machine_name);
499	    }
500	
501	    /**
502	     * Whether this planet holds nothing while a sibling of the same account holds something.
503	     *
504	     * "Holds" is the unit planner's own answer -- built plus already paid for in the yard -- and not the
505	     * built-only count: the account has left its opening the moment its first wall order is placed, so the
506	     * sibling's bare neighbour is reached from that login rather than one login behind a wall that is
507	     * already standing in the queue (QUAL-003: the two planners disagreed about when a wall stands).
508	     */
509	    private function nakedBesideWalled(PlanetService $planet): bool
510	    {
511	        $defence = app(DefenseNeedEvaluator::class);
512	
513	        if ($defence->standingUnits($planet) > 0) {
514	            return false;
515	        }
516	
517	        $player = $planet->getPlayer();
518	        if ($player === null) {
519	            return false;
520	        }
521	
522	        foreach ($player->planets->all() as $sibling) {
523	            if ($sibling->getPlanetId() !== $planet->getPlanetId() && $defence->standingUnits($sibling) > 0) {
524	                return true;
525	            }
526	        }
527	
528	        return false;
529	    }
530	
531	    /** The defence unit the host prices lowest: the smallest thing it will accept as a wall. */
532	    private function smallestDefenceUnit(): ?GameObject
533	    {
534	        $cheapest = null;
535	        $cheapestPrice = INF;
536	
537	        foreach (ObjectService::getDefenseObjects() as $defence) {
538	            $price = ObjectService::getObjectRawPrice($defence->machine_name)->sum();
539	            if ($price <= 0 || $price >= $cheapestPrice) {
540	                continue;
