886	            $bestPrice = $price;
887	        }
888	
889	        if ($best === null) {
890	            return null;
891	        }
892	
893	        $amount = min(
894	            $this->affordable($planet, $best),
895	            max(self::FIRST_CARGO_AMOUNT, (int) ceil(($need?->defenceValue ?? 0.0) / $bestPrice))
896	        );
