916	        }
917	
918	        $price = ObjectService::getObjectPrice($unit->machine_name, $planet);
919	        $held = $planet->getResources();
920	
921	        foreach (['metal', 'crystal', 'deuterium'] as $resource) {
922	            if ($price->{$resource}->get() > 0 && $saving->{$resource}->get() > 0
923	                && $held->{$resource}->get() - $price->{$resource}->get() * $amount < $saving->{$resource}->get()) {
924	                return true;
925	            }
