177	        // own action still owns the primary key: a retried session converges on that action, and the
178	        // wall is one more order in the login rather than the login's objective.
179	        if ($unitsFirst) {
180	            $this->scheduleUnits($profile, $sessionWorkItem, $this->clock->now(), $units, $type === AiCandidateActionType::QueueUnits ? '' : ':wall');
