229	            // The ferry moves stock the buildings were priced against, so it waits for them the way
230	            // the shipyard and the save do: a transfer written at the session's own instant runs
231	            // between the second and third planet's build and the host then refuses those builds,
232	            // leaving the planets idle until the next login.
233	            AiCandidateActionType::Transfer => $this->scheduleTransfer($profile, $sessionWorkItem, $this->clock->now()->addSeconds($economySteps * self::SECONDS_BETWEEN_PLANETS)),
234	            AiCandidateActionType::Recycle => $this->scheduleRecycle($profile, $sessionWorkItem),
235	            AiCandidateActionType::FleetSave => $this->scheduleFleetSave($profile, $sessionWorkItem, $this->clock->now()->addSeconds($economySteps * self::SECONDS_BETWEEN_PLANETS)),
236	            AiCandidateActionType::Recall => $this->scheduleRecall($profile, $sessionWorkItem),
237	            AiCandidateActionType::Spy => $this->scheduleSpy($profile, $sessionWorkItem),
238	            AiCandidateActionType::Raid => $this->scheduleRaid($profile, $sessionWorkItem, $trace),
239	            AiCandidateActionType::ThrottleMine => $this->scheduleMinePercent($profile, $sessionWorkItem),
240	            AiCandidateActionType::Phalanx => $this->schedulePhalanx($profile, $sessionWorkItem),
241	            AiCandidateActionType::DoNothing => $this->recordQuietDecision($profile, $trace),
242	        };
243	
244	        // The war fleet's own order, on a login that chose something else: a player with a war chest
245	        // keeps the shipyard busy whichever page they opened, so the surplus buys the best hull the
246	        // yard can build without waiting for the sessions the engine happens to pick the shipyard. The
247	        // fleet is asked of the planner directly rather than read from the plan above, which only
248	        // carries it when no other role on any planet wanted anything: a login is almost always
249	        // consumed by a probe, a colony ship or a wall, so the plan the schedule was handed never held
250	        // a hull and the account bought none (measured live: 160 QueueUnits orders in half an hour and
251	        // no hull above the median military hull anywhere in the cohort). It is written after the
252	        // building steps, which are priced against the balance first, and a session that decided
253	        // nothing is one with no intent to spend.
254	        $capital = $units instanceof QueueableUnit && $units->surplusSpend
255	            ? $units
256	            : $this->queueableUnitPlanner->capitalFleetOrder($profile->player_id);
257	
258	        // A player whose yard still holds an unfinished order does not click buy again: the surplus
259	        // hull is a habit, not an errand, and a login that ordered on top of an unfinished batch
260	        // buried the shipyard under identical hulls (measured live 3 Oct 2026: 425 unit orders in
261	        // half an hour against 1,057 buildings). The wall orders above are untouched: keeping a
262	        // planet alive is what the yard is for.
263	        if ($capital !== null
264	            && ! $this->shipyardsBusy($profile->player_id)
265	            && ! ($type === AiCandidateActionType::QueueUnits && $units === $capital)
266	            && $type !== AiCandidateActionType::DoNothing) {
267	            $this->scheduleUnits($profile, $sessionWorkItem, $this->clock->now()->addSeconds($economySteps * self::SECONDS_BETWEEN_PLANETS), $capital, ':capital');
268	        }
269	    }
