  3	namespace Modules\AI\Domain\Decision;
  4	
  5	use Modules\AI\Domain\Persona\SavingsGoal;
  6	use Modules\AI\Enums\AiStockpileStrategy;
  7	use Modules\AI\Models\AiProfile;
  8	use OGame\Factories\PlayerServiceFactory;
  9	use OGame\GameObjects\Models\Enums\GameObjectType;
 10	use OGame\Models\Resources;
 11	use OGame\Models\User;
 12	use OGame\Services\BuildingQueueService;
 13	use OGame\Services\ObjectService;
 14	use OGame\Services\PlanetService;
 15	use OGame\Services\PlayerService;
 16	use OGame\Services\ResearchQueueService;
 17	
 18	/**
 19	 * Answers one question about the account's own economy: is there a building or a technology it can
 20	 * legally queue now, and on which planet?
 21	 *
 22	 * Two things want a building. The chain wants the facility a later capability cannot exist without
 23	 * -- an account with no research lab can never research, and one with no shipyard can never own a
 24	 * ship -- and the economy wants the upgrade that repays itself fastest, or the storage that is about
 25	 * to overflow. The plan runs in two passes across the account's planets: first a warehouse that is
 26	 * about to overflow anywhere (it stops that planet producing, so it outranks every routine step on
 27	 * every other planet), then the routine economy planet by planet -- the energy a planet needs before
 28	 * it throttles, the chain's facilities, then the fastest-paying mine. The cross-planet storage pass
 29	 * is what keeps a full warehouse on one colony from waiting behind a routine mine on the homeworld.
 30	 *
 31	 * Both are only suggestions. Every gate is the host's own -- planet type, free queue space,
 32	 * requirements met against what is built *and* queued, and a price the planet can pay, which is the
 33	 * same set the building page shows a human -- so the module never restates an OGame rule. A target
 34	 * the host rejects is not an error but a fall-through: the planner tries the next one, which is what
 35	 * keeps a single impossible favourite from costing the account its whole build capability.
 36	 *
 37	 * Affordability is a real gate rather than a nicety: `BuildingQueueService::start()` cancels a queue
 38	 * item it cannot pay for, so publishing `build` while short of resources spends a queue slot and
 39	 * reports nothing at all.
 40	 */
 41	class QueueableBuildingPlanner
 42	{
 43	    /** The lab is one queue for the account, so its step has one slot beside the per-planet building steps. */
 44	    private const LAB_STEP = 'lab';
 45	
 46	    /** The pass that stands the facilities a bare planet's wall waits on: it is a fix, not a choice. */
 47	    private const WALL_STEP = 'wall';
 48	
 49	    public function __construct(
 50	        private PlayerServiceFactory $playerServiceFactory,
 51	        private FacilityChain $facilityChain,
 52	        private EnergyCapacity $energyCapacity,
 53	        private EconomyUpgrades $economyUpgrades,
 54	        private ReserveFloor $reserveFloor,
 55	        private BuildingQueueService $buildingQueueService,
 56	        private ResearchQueueService $researchQueueService,
 57	    ) {
 58	    }
 59	
 60	    public function plan(int $playerId, ?PlayerService $player = null): QueueableBuilding|QueueableResearch|null
 61	    {
 62	        return $this->steps($playerId, $player, 1)[0] ?? null;
 63	    }
 64	
 65	    /**
 66	     * Every queue a player would fill in one login: at most one building per planet, because each planet
 67	     * pays from its own stock and has its own build queue, and at most one technology, because the
 68	     * lab is one queue for the account. The order is plan()'s, so the first step is the one plan()
 69	     * returns.
 70	     *
 71	     * @return list<QueueableBuilding|QueueableResearch>
 72	     */
 73	    public function steps(int $playerId, ?PlayerService $player = null, int $limit = PHP_INT_MAX): array
 74	    {
 75	        // An account the module does not manage has no policy to apply, so it gets no capability.
 76	        $profile = AiProfile::query()->where('player_id', $playerId)->where('enabled', true)->first();
 77	        if ($profile === null) {
 78	            return [];
 79	        }
 80	
 81	        // The module owns profile rows; the host owns accounts. A profile can outlive its account or
 82	        // be written by a fixture, and loading an account the host does not have throws -- so the
 83	        // precondition is asked here rather than discovered in the host service.
 84	        if (!User::query()->whereKey($playerId)->exists()) {
 85	            return [];
 86	        }
 87	
 88	        // Refresh every planet's live balance once: the candidate pass reads stored amounts and
 89	        // energy, and a balance read stale is exactly the balance the queue later cancels on. The
 90	        // refresh stays in memory -- the observation path must not write.
 91	        $planets = ($player ?? $this->playerServiceFactory->make($playerId, true))->planets->all();
 92	        foreach ($planets as $planet) {
 93	            $planet->updateResources(false);
 94	            $planet->updateResourceProductionStats(false);
 95	            $planet->updateResourceStorageStats(false);
