161	     * @param callable(PlanetService): list<BuildCandidate> $pass
162	     * @return array<int|string, QueueableBuilding|QueueableResearch>
163	     */
164	    private function withStep(array $steps, PlanetService $planet, AiProfile $profile, callable $pass, ?SavingsGoal $goal, bool $wall = false): array
165	    {
166	        $candidates = $pass($planet);
167	        $isResearch = static fn (BuildCandidate $candidate): bool => ObjectService::getObjectById($candidate->buildingId)->type === GameObjectType::Research;
