248	        $machineName = $object->machine_name;
249	
250	        if (!ObjectService::objectValidPlanetType($machineName, $planet)) {
251	            return 'planet type';
252	        }
253	        if ($this->buildingQueueService->retrieveQueue($planet)->isQueueFull()) {
254	            return 'queue full';
