  3	namespace Modules\AI\Jobs;
  4	
  5	use Illuminate\Contracts\Queue\ShouldQueue;
  6	use Illuminate\Foundation\Queue\Queueable;
  7	use Illuminate\Support\Facades\Cache;
  8	use Illuminate\Support\Facades\DB;
  9	use Illuminate\Support\Facades\Log;
 10	use Illuminate\Support\Str;
 11	use Modules\AI\Actions\ExecuteAiIntentAction;
 12	use Modules\AI\Actions\ResolveAiAdmissionAction;
 13	use Modules\AI\Contracts\RunAiSession;
 14	use Modules\AI\Enums\AiActionReceiptResultKey;
 15	use Modules\AI\Enums\AiQueueActionReason;
 16	use Modules\AI\Enums\AiQueueName;
 17	use Modules\AI\Enums\AiReceiptState;
 18	use Modules\AI\Enums\AiWorkKind;
 19	use Modules\AI\Enums\AiWorkState;
 20	use Modules\AI\Models\AiActionReceipt;
 21	use Modules\AI\Models\AiProfile;
 22	use Modules\AI\Models\AiSchedule;
 23	use Modules\AI\Models\AiWorkItem;
 24	use OGame\Models\Planet;
 25	use Throwable;
 26	
 27	class ProcessAiWork implements ShouldQueue
 28	{
 29	    use Queueable;
 30	
 31	    public int $tries = 3;
 32	
 33	    /** Bounds a poison work item; retryLease() owns the work-item attempt cap. */
 34	    public int $maxExceptions = 3;
 35	
 36	    /**
 37	     * Leave margin below the module's Horizon timeout so a worker is not force-killed
 38	     * mid-decision. The grand run raises both values for hybrid driver contention.
 39	     */
 40	    public int $timeout;
 41	
 42	    private const PAYLOAD_PLANET_ID = 'planet_id';
 43	
 44	    public function __construct(public int $workItemId)
 45	    {
 46	        $this->timeout = max(1, (int) config('ai.horizon.supervisors.supervisor-ai.timeout', 30) - 5);
 47	
 48	        // Deterministic AI work has its own module-owned Horizon lane so AI volume
 49	        // cannot starve the general or fleet lanes.
 50	        $this->onQueue(AiQueueName::Ai->value);
 51	    }
 52	
 53	    /** @return list<string> */
 54	    public function tags(): array
 55	    {
 56	        return ['ai', 'ai:work', 'ai:work-item:' . $this->workItemId];
 57	    }
 58	
 59	    public function failed(Throwable $exception): void
 60	    {
 61	        Log::error('AI work item failed after all queue attempts', [
 62	            'work_item_id' => $this->workItemId,
 63	            'error' => $exception->getMessage(),
 64	        ]);
 65	
 66	        $this->scheduleSessionRecovery();
 67	    }
 68	
 69	    public function handle(): void
 70	    {
 71	        // A switch that is off stops new decisions without discarding the work: the item stays
 72	        // pending and the first pass after it is switched back on picks it up again.
 73	        if (!app(ResolveAiAdmissionAction::class)->forWorkItem()->allowed) {
 74	            return;
 75	        }
 76	
 77	        $leaseToken = (string) Str::uuid();
 78	        // Claim before side effects. Every terminal update checks this token so
 79	        // a slow worker cannot complete work leased again by another worker.
 80	        $workItem = $this->claimDueWork($leaseToken);
 81	
 82	        if ($workItem === null) {
 83	            return;
 84	        }
 85	
 86	        $lock = Cache::lock('ai:player:' . $workItem->player_id, 300);
 87	        if (!$lock->get()) {
 88	            $this->retryContendedLease($workItem, $leaseToken);
 89	
 90	            return;
 91	        }
 92	
 93	        try {
 94	            $profile = AiProfile::query()->where('player_id', $workItem->player_id)->where('enabled', true)->first();
 95	            if ($profile === null) {
 96	                $this->completeLease($workItem, $leaseToken);
 97	
 98	                return;
 99	            }
100	
101	            if ($workItem->kind === AiWorkKind::RunSession) {
102	                $this->runClaimedSession($profile, $workItem, $leaseToken);
103	
104	                return;
105	            }
106	
107	            $this->queueClaimedIntent($profile, $workItem, $leaseToken);
108	        } catch (Throwable $exception) {
109	            $this->retryLease($workItem, $leaseToken);
110	
111	            throw $exception;
112	        } finally {
113	            $lock->release();
114	        }
115	    }
116	
117	    private function claimDueWork(string $leaseToken): AiWorkItem|null
118	    {
119	        return DB::transaction(function () use ($leaseToken): AiWorkItem|null {
120	            /** @var AiWorkItem|null $workItem */
121	            $workItem = AiWorkItem::query()->lockForUpdate()->find($this->workItemId);
122	            if ($workItem === null || (!$this->acceleratedSession($workItem) && $workItem->due_at->isFuture()) || !$this->isClaimable($workItem)) {
123	                return null;
124	            }
125	
126	            $workItem->update([
127	                'state' => AiWorkState::Leased,
128	                'lease_token' => $leaseToken,
129	                'lease_until' => now()->addMinutes(5),
130	                'attempts' => $workItem->attempts + 1,
131	            ]);
132	
133	            return $workItem->fresh();
134	        });
135	    }
136	
137	    private function acceleratedSession(AiWorkItem $workItem): bool
138	    {
139	        return $workItem->kind === AiWorkKind::RunSession
140	            && (int) config('ai.population.session_interval_seconds', 0) > 0;
141	    }
142	
143	    private function isClaimable(AiWorkItem $workItem): bool
144	    {
145	        if (in_array($workItem->state, [AiWorkState::Pending, AiWorkState::Retry], true)) {
146	            return true;
147	        }
148	
149	        // A worker killed mid-handle leaves the item Leased; reclaim it once the lease
150	        // expires so a queue retry or the scheduler can finish the work instead of the
151	        // item staying stuck forever.
152	        return $workItem->state === AiWorkState::Leased
153	            && $workItem->lease_until !== null
154	            && $workItem->lease_until->isPast();
155	    }
156	
157	    private function runClaimedSession(AiProfile $profile, AiWorkItem $workItem, string $leaseToken): void
158	    {
159	        app(RunAiSession::class)->handle($profile, $workItem);
160	        $this->completeLease($workItem, $leaseToken);
161	    }
162	
163	    private function queueClaimedIntent(AiProfile $profile, AiWorkItem $workItem, string $leaseToken): void
164	    {
165	        // The action cap bounds what a session may touch, not what it may think: at zero the
166	        // session already decided and scheduled, so this pass closes its lease and acts on
167	        // nothing.
168	        if (!app(ResolveAiAdmissionAction::class)->forAction()->allowed) {
169	            $this->completeLease($workItem, $leaseToken);
170	
171	            return;
172	        }
173	
174	        $receipt = AiActionReceipt::query()->firstOrCreate(
175	            ['idempotency_key' => $workItem->idempotency_key],
176	            [
177	                'player_id' => $workItem->player_id,
178	                'action_type' => $workItem->kind->actionType(),
179	                'state' => AiReceiptState::Processing,
180	            ],
181	        );
182	        if (in_array($receipt->state, [AiReceiptState::Accepted, AiReceiptState::Completed, AiReceiptState::Rejected], true)) {
183	            $this->completeLease($workItem, $leaseToken);
184	
185	            return;
186	        }
187	
188	        $planetId = $this->ownedPlanetIdFor($workItem);
189	        if ($planetId === 0) {
190	            $receipt->update(['state' => AiReceiptState::Rejected, 'result' => [AiActionReceiptResultKey::Reason->value => AiQueueActionReason::NoOwnedPlanet->value]]);
191	            $this->completeLease($workItem, $leaseToken);
192	
193	            return;
194	        }
195	
196	        // An intent that names a body this account does not own is not this account's to act on, and
197	        // re-planning it onto a different one would silently change what the session decided.
198	        if (!Planet::query()->whereKey($planetId)->where('user_id', $workItem->player_id)->exists()) {
199	            $receipt->update(['state' => AiReceiptState::Rejected, 'result' => [AiActionReceiptResultKey::Reason->value => AiQueueActionReason::PlanetNotOwned->value]]);
200	            $this->completeLease($workItem, $leaseToken);
201	
202	            return;
203	        }
204	
205	        [$result, $decision, $actedPlanetId] = app(ExecuteAiIntentAction::class)->execute($workItem, $planetId);
206	        if ($result === null) {
207	            $receipt->update(['state' => AiReceiptState::Rejected, 'result' => [AiActionReceiptResultKey::Reason->value => AiQueueActionReason::NothingQueueable->value]]);
208	            $this->completeLease($workItem, $leaseToken);
209	
210	            return;
211	        }
212	
213	        $receipt->update([
214	            'state' => $result->successful ? AiReceiptState::Accepted : AiReceiptState::Rejected,
215	            'result' => [
216	                AiActionReceiptResultKey::QueueId->value => $result->queueId,
217	                AiActionReceiptResultKey::Reason->value => $result->reason,
218	                AiActionReceiptResultKey::Decision->value => $decision,
219	                AiActionReceiptResultKey::PlanetId->value => $actedPlanetId,
220	            ],
221	        ]);
222	        $this->completeLease($workItem, $leaseToken);
223	    }
224	
225	    private function ownedPlanetIdFor(AiWorkItem $workItem): int
226	    {
227	        return (int) ($workItem->payload[self::PAYLOAD_PLANET_ID] ?? Planet::query()->where('user_id', $workItem->player_id)->value('id'));
228	    }
229	
230	    private function completeLease(AiWorkItem $workItem, string $leaseToken): void
231	    {
232	        AiWorkItem::query()->whereKey($workItem->id)->where('lease_token', $leaseToken)->update([
233	            'state' => AiWorkState::Completed, 'lease_token' => null, 'lease_until' => null,
234	        ]);
235	    }
236	
237	    private function retryLease(AiWorkItem $workItem, string $leaseToken): void
238	    {
239	        $failed = $workItem->attempts >= $this->tries;
240	
241	        AiWorkItem::query()->whereKey($workItem->id)->where('lease_token', $leaseToken)->update([
242	            'state' => $failed ? AiWorkState::Failed : AiWorkState::Retry,
243	            'due_at' => now()->addMinute(),
244	            'lease_token' => null,
245	            'lease_until' => null,
246	        ]);
247	
248	        if ($failed) {
249	            $this->scheduleSessionRecovery();
250	        }
251	    }
252	
253	    private function retryContendedLease(AiWorkItem $workItem, string $leaseToken): void
254	    {
255	        AiWorkItem::query()->whereKey($workItem->id)->where('lease_token', $leaseToken)->update([
256	            'state' => AiWorkState::Retry,
257	            'due_at' => now()->addSeconds(5),
258	            'attempts' => 0,
259	            'lease_token' => null,
260	            'lease_until' => null,
261	        ]);
262	    }
263	
264	    private function scheduleSessionRecovery(): void
265	    {
266	        DB::transaction(function (): void {
267	            $workItem = AiWorkItem::query()
268	                ->lockForUpdate()
269	                ->find($this->workItemId);
270	
271	            if ($workItem === null || $workItem->kind !== AiWorkKind::RunSession || $workItem->state !== AiWorkState::Failed) {
272	                return;
273	            }
274	
275	            $schedule = AiSchedule::query()
276	                ->where('player_id', $workItem->player_id)
277	                ->lockForUpdate()
278	                ->first();
279	
280	            if ($schedule === null) {
281	                return;
282	            }
283	
284	            if ($schedule->generation > (int) $workItem->schedule_generation) {
285	                return;
286	            }
287	
288	            $nextGeneration = max($schedule->generation, (int) $workItem->schedule_generation) + 1;
